---
'use strict';
// Shared shopping list: HTTP API + durable storage (JSON file, fsync'd) + static web UI.
const http = require('http');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const PORT = parseInt(process.env.PORT || '8080', 10);
const DATA_DIR = process.env.DATA_DIR || path.join(__dirname, 'data');
const DATA_FILE = path.join(DATA_DIR, 'list.json');
const PUBLIC_DIR = path.join(__dirname, 'public');
const MAX_BODY = 64 * 1024;

// Bumped on every change; the UI polls /api/list?since=N to see others' changes fast.
let seq = 1;
let nextId = 1;
let items = []; // {id, text, bought, createdAt, updatedAt, updatedBy}

function load() {
  try {
    fs.mkdirSync(DATA_DIR, { recursive: true });
    const raw = fs.readFileSync(DATA_FILE, 'utf8');
    const data = JSON.parse(raw);
    if (Array.isArray(data.items)) items = data.items;
    nextId = Number.isInteger(data.nextId) && data.nextId > 0 ? data.nextId : 1;
    seq = Number.isInteger(data.seq) && data.seq > 0 ? data.seq : 1;
    for (const it of items) if (Number.isInteger(it.id) && it.id >= nextId) nextId = it.id + 1;
    console.log(`loaded ${items.length} item(s) from ${DATA_FILE}`);
  } catch (e) {
    if (e.code !== 'ENOENT') {
      console.error('could not read data file, starting empty:', e.message);
      try { fs.copyFileSync(DATA_FILE, DATA_FILE + '.corrupt-' + Date.now()); } catch (_) {}
    }
    items = []; nextId = 1; seq = 1;
  }
}

// Durable write: temp file, fsync, atomic rename, fsync dir.
function save() {
  fs.mkdirSync(DATA_DIR, { recursive: true });
  const tmp = DATA_FILE + '.tmp';
  const payload = JSON.stringify({ seq, nextId, items });
  const fd = fs.openSync(tmp, 'w');
  try {
    fs.writeSync(fd, payload);
    fs.fsyncSync(fd);
  } finally { fs.closeSync(fd); }
  fs.renameSync(tmp, DATA_FILE);
  try { const dfd = fs.openSync(DATA_DIR, 'r'); fs.fsyncSync(dfd); fs.closeSync(dfd); } catch (_) {}
}

function touch(who) {
  seq += 1;
  save();
}

function publicItem(it) {
  return { id: it.id, text: it.text, bought: !!it.bought, createdAt: it.createdAt, updatedAt: it.updatedAt, updatedBy: it.updatedBy };
}

